import { useState } from "react";
import { motion } from "framer-motion";

function Contact() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    message: ""
  });
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // yaha tum apna EmailJS ya API call karoge
    console.log("Form submitted:", formData);

    // ✅ Auto refresh (clear fields)
    setFormData({ name: "", email: "", message: "" });

    // ✅ Trigger animation
    setSubmitted(true);

    // Animation ko 3 sec baad hide karna
    setTimeout(() => setSubmitted(false), 3000);
  };

  return (
    <section id="contact" className="p-6 bg-gray-900 text-white">
      <h2 className="text-2xl mb-4">Contact Me</h2>

      <form onSubmit={handleSubmit} className="flex flex-col gap-4">
        <input
          type="text"
          name="name"
          placeholder="Your Name"
          value={formData.name}
          onChange={handleChange}
          className="p-2 rounded bg-gray-800"
        />
        <input
          type="email"
          name="email"
          placeholder="Your Email"
          value={formData.email}
          onChange={handleChange}
          className="p-2 rounded bg-gray-800"
        />
        <textarea
          name="message"
          placeholder="Your Message"
          value={formData.message}
          onChange={handleChange}
          className="p-2 rounded bg-gray-800"
        />
        <button
          type="submit"
          className="bg-blue-600 hover:bg-blue-700 p-2 rounded"
        >
          Send Message
        </button>
      </form>

      {/* ✅ Success Animation */}
      {submitted && (
        <motion.div
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0.5 }}
          className="mt-4 text-green-400 font-semibold"
        >
          🎉 Message Sent Successfully!
        </motion.div>
      )}
    </section>
  );
}

export default Contact;
